use crate::api::{
    client::{HaiClient, RequestError},
    types::asset::{AssetEntry, AssetGetArg, AssetGetError},
};

/// If `asset_name` is an attachment, this recursively queries the parent of
/// the attachment, which might be another attachment, until it arrives at the
/// attachment's anchor asset.
///
/// Use this to check access to an asset name since permissons are applied to
/// attachment anchors rather than the attachments themselves.
///
/// Attachment name format: `:<attachment_parent_entry_id>:<attachment_name>`
///
/// # Returns
///
/// The attachment anchor entry. If the input `asset_name` wasn't an
/// attachment, then the entry for `asset_name` is returned.
pub async fn resolve_perm_granting_asset_entry(
    api_client: &HaiClient,
    asset_name: &str,
) -> Result<AssetEntry, (String, RequestError<AssetGetError>)> {
    let mut entry = if let Some(entry_id) = parse_attachment_parent_entry_id(asset_name) {
        // `asset_name` is an attachment so skip ahead to parent entry
        // NOTE: This also desirably skips attachments have yet to be created,
        // which is necessary when evaluating write permissions for a new attachment.
        match api_client
            .asset_get(AssetGetArg {
                name: entry_id.clone(),
            })
            .await
        {
            Ok(get_res) => get_res.entry,
            Err(e) => return Err((entry_id, e)),
        }
    } else {
        // Handles cases:
        // 1. entry_id to non-attachment
        // 2. entry_id to attachment
        // 3. regular name (non-entry_id) to non-attachment
        match api_client
            .asset_get(AssetGetArg {
                name: asset_name.to_string(),
            })
            .await
        {
            Ok(get_res) => get_res.entry,
            Err(e) => return Err((asset_name.to_string(), e)),
        }
    };

    loop {
        tracing::debug!(?entry.name, "resolved_attachment_anchor_asset_entry");
        let Some(entry_id) = parse_attachment_parent_entry_id(&entry.name) else {
            // Not an attachment, found anchor.
            return Ok(entry);
        };

        entry = match api_client
            .asset_get(AssetGetArg {
                name: entry_id.clone(),
            })
            .await
        {
            Ok(get_res) => get_res.entry,
            Err(e) => return Err((entry_id, e)),
        };
    }
}

/// Attachment name format: `:<attachment_parent_entry_id>:<attachment_name>`
///
/// # Returns
///
/// If `name` is an attachment, returns the `attachment_parent_entry_id`.
/// Otherwise, returns None.
pub fn parse_attachment_parent_entry_id(name: &str) -> Option<String> {
    let rest = name.strip_prefix(':')?;
    let idx = rest.find(':')?;
    let entry_id = &rest[..idx];
    Some(format!(":{entry_id}"))
}

// --

/// Checks permission to access an asset across multiple dimensions.
///
/// 1. entry_id (with : prefix)
/// 2. asset_name
/// 3. resolving attachment to asset_name / entry_id
///
/// # Returns
///
/// True if user has the necessary permission.
pub async fn access_perm_for_asset_access_request(
    api_client: &HaiClient,
    asset_name: &str,
    perms: &[&Perm],
    write: bool,
) -> Result<bool, (String, RequestError<AssetGetError>)> {
    // Quick exit: Try to check access by the `asset_name` given to see if we
    // can avoid any extra queries.
    if asset_helper::is_entry_id(asset_name) {
        let access_req = if write {
            AccessRequest::WriteByEntryId {
                entry_id: asset_name,
            }
        } else {
            AccessRequest::ReadByEntryId {
                entry_id: asset_name,
            }
        };
        if check_access(&perms, &access_req).is_ok() {
            return Ok(true);
        }
    } else {
        let access_req = if write {
            AccessRequest::WriteByName { name: asset_name }
        } else {
            AccessRequest::ReadByName { name: asset_name }
        };
        if check_access(&perms, &access_req).is_ok() {
            return Ok(true);
        }
    }

    // If the quick exit didn't work, we need to resolve the full perm-granting
    // entry (attachment anchor, if applicable) and try both the name and
    // entry_id. NOTE: Could be optimized to use fewer queries on average.
    let perm_granting_asset_entry =
        resolve_perm_granting_asset_entry(api_client, asset_name).await?;
    let access_req_by_name = if write {
        AccessRequest::WriteByName {
            name: &perm_granting_asset_entry.name,
        }
    } else {
        AccessRequest::ReadByName {
            name: &perm_granting_asset_entry.name,
        }
    };
    if check_access(&perms, &access_req_by_name).is_ok() {
        return Ok(true);
    }
    let access_req_by_entry_id = if write {
        AccessRequest::WriteByEntryId {
            entry_id: &perm_granting_asset_entry.entry_id,
        }
    } else {
        AccessRequest::ReadByEntryId {
            entry_id: &perm_granting_asset_entry.entry_id,
        }
    };
    if check_access(&perms, &access_req_by_entry_id).is_ok() {
        return Ok(true);
    }
    Ok(false)
}

// --

/// Checks permission to list a prefix across multiple dimensions.
///
/// 1. List prefix access is superset of asset_prefix.
/// 2. Read access to perm-granting asset (attachment anchor).
///
/// # Returns
///
/// True if user has the necessary permission.
pub async fn access_perm_for_asset_list_prefix_request(
    api_client: &HaiClient,
    asset_prefix: &str,
    perms: &[&Perm],
) -> Result<bool, (String, RequestError<AssetGetError>)> {
    // Quick exit: Try to check access by the `asset_prefix` given to see if we
    // can avoid any extra queries.
    let access_req = AccessRequest::ListPrefix {
        prefix: asset_prefix,
    };
    if check_access(&perms, &access_req).is_ok() {
        return Ok(true);
    }

    if asset_helper::is_attachment(asset_prefix) {
        // If it's an attachment, get the perm-granting asset and check if we
        // have read permissions to it.
        let perm_granting_asset_entry =
            resolve_perm_granting_asset_entry(api_client, asset_prefix).await?;
        let access_req_by_name = AccessRequest::ReadByName {
            name: &perm_granting_asset_entry.name,
        };
        if check_access(&perms, &access_req_by_name).is_ok() {
            return Ok(true);
        }
        let access_req_by_entry_id = AccessRequest::ReadByEntryId {
            entry_id: &perm_granting_asset_entry.entry_id,
        };
        if check_access(&perms, &access_req_by_entry_id).is_ok() {
            return Ok(true);
        }
    }
    Ok(false)
}
